Ltac rdn_bytes :=
  repeat (apply rdn_cons; [lia | cbn; lia | (match goal with |- rdn _ _ (Z_to_bv 64 ?a) 1 = _ => try (progress (ring_simplify a)) end; match goal with H : L5.u8_at _ _ ?a _ |- rdn _ _ (Z_to_bv 64 ?a) 1 = _ => exact H end) | ]);
  reflexivity.

Section UA.
  Context (fx : FPState).
  Variables (R : bvmap 5 word) (M : word -> option byte) (S p can : Z) (bs t8 : list byte).
  #[local] Notation n := (Z.of_nat (length bs)).
  Hypothesis G1 : getr R (reg 1) = Z_to_bv 64 716616.
  Hypothesis G2 : getr R (reg 2) = Z_to_bv 64 S.
  Hypothesis G10 : getr R (reg 10) = Z_to_bv 64 1407328.
  Hypothesis G11 : getr R (reg 11) = Z_to_bv 64 129589.
  Hypothesis G12 : getr R (reg 12) = Z_to_bv 64 p.
  Hypothesis HS : 140735332552704 + 5440 <= S <= 140737488355328.
  Hypothesis Hal : S mod 16 = 0.
  Hypothesis HW : L5.writable RSEGS M (S - 5440) 5440.
  Hypothesis HD : L5.defined M (S - 5440) 5440.
  Hypothesis HIMG : L5.img_clear M 65536 1392640.
  Hypothesis Hp : S <= p /\ p + n + 1 + 16 <= 2 ^ 47.
  Hypothesis Hn : 64 <= n <= 131071.
  Hypothesis HSTR : cstr M p bs t8.
  Hypothesis HSH : forall x : word, SB + p / 8 - 7 <= bv_unsigned x < Z.min (SB + (p + n) / 8 + 8) (SB + 2 ^ 44) -> M x = Some (Z_to_bv 8 0).
  Hypothesis HSTK : L5KA.zeros_at M (SB + S / 8 - 680) 688.
  Hypothesis HFMT : L5KA.zeros_at M 2147467072 16.
  Hypothesis Hcan : 0 <= can < 2 ^ 64.
  Hypothesis HC : diag_cells M can.
  Hypothesis HSN : sn_cells M.
  Hypothesis HMC : mc_icpt_globs M.

  Definition PRE17 : list byte := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;Y3;0;A1;i0;A1;o1;#0;A1;i12;#1;A1;o1;Y6;00;m2;RNLx;RA1;i2;#2;#2;A4;k20;k10;L~RA1;i0;#3;A1;o73;#1;A2;k16;#3;A1;o7;Y16;fa35;N17;2;Ll;R#2;r1;A1;o18;#1;").
  Definition SUF1 : list byte := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S4;Y3;0;A1;i0;A1;o1;#0;A1;i12;#1;A1;o1;Y6;00;m2;RNLx;RA1;i2;#2;#2;A4;k20;k10;L~RA1;i0;#3;A1;o73;#1;A2;k16;#3;A1;o7;Y16;fa48;N1;2;Ll;R#2;r1;A1;o18;#1;").
  Lemma suf1_img : rdn RSEGS (fun _ => None) (Z_to_bv 64 129608) 1 = Some SUF1.  Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S6;Y3;0;A1;i0;A1;o1;#0;A1;i12;#1;A1;i2;#2;A2;o21;#2;k78;A1;o1;Y6;00;cvA2;o19;#3;#4;A3;i11;#3;A4;k20;k10;L~RA1;i0;#5;A1;o73;#1;A2;k16;#5;A1;o7;Y16;fa48;N1;#4;").
Qed.
  Lemma PRE17_eq : PRE17 = map (Z_to_bv 8) [99; 108; 105; 58; 32; 99; 97; 110; 110; 111; 116; 32; 111; 112; 101; 110; 32].
  Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S12;Y3;0;A1;o1;#0;A1;i0;#1;A1;o7;Y6;23;Y5;1a;A1;o7;Y5;00;A1;o7;Y6;2e;A1;o7;Y6;2f;A3;o17;i3;#3;A3;o17;i3;A1;o7;Y6;2c;A3;o17;i3;A1;o7;Y6;29;A3;o17;i3;A1;o7;#4;A3;o17;i3;#5;A3;o17;i3;#3;A3;o17;i3;A1;o7;Y6;21;A3;o17;i3;#6;A3;o17;i3;#6;A3;o17;i3;#7;A3;o17;i3;A1;o7;Y6;34;A3;o17;i3;#5;A3;o17;i3;#7;A3;o17;i3;A1;o7;Y6;30;A3;o17;i3;A1;o7;Y6;25;A3;o17;i3;#6;A3;o17;i3;#5;A1;o18;i3;A4;k13;i3;#2;A1;k16;#1;#8;A1;i12;i3;A1;k14;#1;A3;k79;k80;#9;cvA2;o19;#10;#8;A3;i11;#10;A4;k13;#2;i3;#11;k80;A4;k13;#2;i3;#11;#9;").
